function HornSlopeSq(z00: real, z01: real, z02: real, z10: real, z11: real, z12: real, z20: real, z21: real, z22: real, w: real): real
 requires w > 0.0
{

 var dzdx := (z02 + 2.0*z12 + z22 - z00 - 2.0*z10 - z20) / (8.0 * w);
 var dzdy := (z00 + 2.0*z01 + z02 - z20 - 2.0*z21 - z22) / (8.0 * w);

 dzdx*dzdx + dzdy*dzdy
}

